def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = max(
        range(10),
        key=lambda color: sum(cell == color for row in grid for cell in row)
    )

    # Each diagonal pair defines a line; extend from both ends through
    # background cells, stopping at the edge or another colored cell.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= cc < w) or grid[rr][cc] != color:
                    continue

                for sr, sc, start_r, start_c in (
                    (-dr, -dc, r, c),
                    (dr, dc, rr, cc),
                ):
                    nr, nc = start_r + sr, start_c + sc
                    while 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background:
                        out[nr][nc] = color
                        nr += sr
                        nc += sc

    return out
